from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    """
    rules:
        [
            {
                "match_type": "path_prefix" | "host" | "query_param",
                "match_value": str,
                "action": "strip_prefix" | "redirect_host"
                          | "add_query_param" | "block",
                "action_value": str,  # block の場合は省略可
            },
            ...
        ]

    urls:
        URL文字列のリスト

    Returns:
        書き換え後のURLまたは None のリスト
    """

    def replace_host(parsed, new_host):
        """ホスト名だけを置き換え、ユーザー情報とポートは維持する。"""
        netloc = parsed.netloc

        # ユーザー情報を分離
        if "@" in netloc:
            userinfo, authority = netloc.rsplit("@", 1)
            userinfo += "@"
        else:
            userinfo = ""
            authority = netloc

        # 元のポート部分を維持
        port_part = ""
        if authority.startswith("["):
            # IPv6
            closing_bracket = authority.find("]")
            if closing_bracket != -1:
                port_part = authority[closing_bracket + 1:]
        else:
            colon_pos = authority.rfind(":")
            if colon_pos != -1 and authority[colon_pos + 1:].isdigit():
                port_part = authority[colon_pos:]

        # IPv6形式のホストは角括弧で囲む
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        new_netloc = userinfo + new_host + port_part

        return urlunsplit((
            parsed.scheme,
            new_netloc,
            parsed.path,
            parsed.query,
            parsed.fragment,
        ))

    def matches(parsed, rule):
        match_type = rule["match_type"]
        match_value = rule["match_value"]

        if match_type == "path_prefix":
            return parsed.path.startswith(match_value)

        if match_type == "host":
            host = (parsed.hostname or "").lower()
            value = match_value.lower()

            if value.startswith("*."):
                suffix = value[2:]
                # ドメインそのものは除外し、厳密なサブドメインだけ許可
                return host.endswith("." + suffix) and host != suffix

            return host == value

        if match_type == "query_param":
            params = parse_qsl(
                parsed.query,
                keep_blank_values=True,
            )
            return any(name == match_value for name, _ in params)

        raise ValueError(f"unknown match_type: {match_type}")

    result = []

    for url in urls:
        rewritten = url

        for rule in rules:
            parsed = urlsplit(url)

            if not matches(parsed, rule):
                continue

            action = rule["action"]

            if action == "block":
                rewritten = None

            elif action == "strip_prefix":
                prefix = rule["action_value"]
                new_path = parsed.path

                if new_path.startswith(prefix):
                    new_path = new_path[len(prefix):]

                if not new_path:
                    new_path = "/"

                rewritten = urlunsplit((
                    parsed.scheme,
                    parsed.netloc,
                    new_path,
                    parsed.query,
                    parsed.fragment,
                ))

            elif action == "redirect_host":
                rewritten = replace_host(
                    parsed,
                    rule["action_value"],
                )

            elif action == "add_query_param":
                addition = rule["action_value"]
                new_query = (
                    f"{parsed.query}&{addition}"
                    if parsed.query
                    else addition
                )

                rewritten = urlunsplit((
                    parsed.scheme,
                    parsed.netloc,
                    parsed.path,
                    new_query,
                    parsed.fragment,
                ))

            else:
                raise ValueError(f"unknown action: {action}")

            # 最初に適合したルールだけを使用
            break

        result.append(rewritten)

    return result
